"""Verify the generated byline separator cannot strand at a line end.

The defect (MEASURED before the fix, WebKit, showcase /f/prose/):
  with `updatedDate` set, the byline wrapped at 320/360/390/402/430 and
  line one ENDED with the `.cm-byline__sep` element at ALL FIVE widths,
  with `updated Sep 26, 2025` alone on line two.

The invariant that discriminates: NO VISUAL LINE ENDS WITH A SEPARATOR.
Measured as: the LAST item on each visual line is not a separator-only
fragment. A `::before` mark is drawn BEFORE its item, so a generated
separator can never be the last thing on a line - that is the mechanism,
and this checks the effect of that mechanism.

Checked in BOTH directions, because either half alone is the same bug
pointing the other way:
  - no separator ELEMENT remains in the DOM (otherwise the ::before would
    double up and the element could still strand);
  - the generated mark is really present on a non-first child, so "no line
    ends with a separator" is not satisfied by the separator vanishing.

Usage: /root/.venvs/mau/bin/python tests/verify-byline-sep.py
"""
import sys
from playwright.sync_api import sync_playwright

URL = "http://192.168.1.68:4471/f/prose/"
WIDTHS = [(320, 667), (360, 780), (390, 844), (402, 874), (430, 932), (1280, 900)]
NARROW = 190  # a card / sidebar / chat bubble: the component's real habitat
SEP_GLYPHS = {"", "\u00b7", "|", "/", "\\", "\u2013", "\u2014", "*"}

PROBE = r"""
(sel) => {
  const byline = document.querySelector(sel);
  if (!byline) return { error: 'no .cm-byline' };
  const kids = [...byline.children].filter(el => el.getBoundingClientRect().height > 0);
  const lines = new Map();
  for (const el of kids) {
    const r = el.getBoundingClientRect();
    const k = Math.round(r.top);
    if (!lines.has(k)) lines.set(k, []);
    lines.get(k).push(el);
  }
  const rows = [...lines.entries()].sort((a, c) => a[0] - c[0]).map(([top, items]) => {
    items.sort((a, c) => a.getBoundingClientRect().left - c.getBoundingClientRect().left);
    const last = items[items.length - 1];
    const first = items[0];
    // The CAUSE: which children own a generated mark. This is the
    // mechanism claim, read from the cascade rather than inferred.
    const marks = items.map(e => ({
      text: e.textContent.trim(),
      mark: getComputedStyle(e, '::before').content,
      sepClass: e.classList.contains('cm-byline__sep'),
    }));
    return {
      top,
      text: items.map(e => e.textContent.trim()).join(' | '),
      items: marks,
      lastText: last.textContent.trim(),
      lastIsSepClass: last.classList.contains('cm-byline__sep'),
      firstLeft: Math.round(first.getBoundingClientRect().left),
      right: Math.round(last.getBoundingClientRect().right),
    };
  });
  return {
    width: Math.round(byline.getBoundingClientRect().width),
    childCount: kids.length,
    sepElements: byline.querySelectorAll('.cm-byline__sep').length,
    // Does ANY non-first child carry a generated mark? That is the fix.
    generatedMarks: [...byline.children].filter(
      (el, i) => i > 0 && getComputedStyle(el, '::before').content.includes('\u00b7')
    ).length,
    rows,
  };
}
"""

report = []
fails = []

with sync_playwright() as p:
    browser = p.webkit.launch()
    for w, h in WIDTHS:
        pg = browser.new_page(viewport={"width": w, "height": h}, device_scale_factor=2)
        pg.set_default_timeout(180000)  # starved box: 27s+ to boot

        pg.emulate_media(reduced_motion="reduce")
        pg.goto(URL, wait_until="networkidle")
        pg.wait_for_function(
            "() => document.documentElement.classList.contains('cm-js') || !!window.cliMono",
            timeout=180000)
        pg.evaluate("() => document.fonts.ready")
        pg.wait_for_timeout(250)

        readings = [("page", pg.evaluate(PROBE, ".cm-byline"))]

        pg.evaluate(
            """(narrow) => {
              const src = document.querySelector('.cm-byline');
              const host = document.createElement('div');
              host.id = '__narrowhost';
              host.style.cssText = 'width:' + narrow + 'px';
              host.appendChild(src.cloneNode(true));
              document.body.appendChild(host);
            }""", NARROW)
        pg.wait_for_timeout(150)
        readings.append((f"narrow{NARROW}", pg.evaluate(PROBE, "#__narrowhost .cm-byline")))
        pg.close()

        for label, r in readings:
            tag = f"{w}x{h} {label}"
            if "error" in r:
                fails.append(f"{tag}: {r['error']}")
                continue
            if r["sepElements"] != 0:
                fails.append(f"{tag}: {r['sepElements']} separator ELEMENT(s) still present "
                             "— the ::before would double up")
            if r["generatedMarks"] == 0 and r["childCount"] > 1:
                fails.append(f"{tag}: NO generated mark on any non-first child "
                             "— 'no line ends with a separator' would be vacuously true")
            for row in r["rows"]:
                if row["lastIsSepClass"] or row["lastText"] in SEP_GLYPHS:
                    fails.append(f"{tag}: a line ENDS with a separator: [{row['text']}]")
            report.append((tag, r))

    browser.close()

print("byline separator — generated on the item it precedes")
print()
for tag, r in report:
    print(f"{tag:<22} width={r['width']:>4} lines={len(r['rows'])} "
          f"sepEls={r['sepElements']} genMarks={r['generatedMarks']}")
    for row in r["rows"]:
        lead = "leads-with-·" if row["items"][0]["mark"].endswith("b7") or "\u00b7" in row["items"][0]["mark"] else ""
        print(f"    [{row['text']}]  x {row['firstLeft']}->{row['right']}  {lead}")

# The runs must DIFFER, or the probe compared one layout to itself.
page_lines = {tag: len(r["rows"]) for tag, r in report if tag.endswith("page")}
print("\npage wrap counts:", page_lines)
if len(set(page_lines.values())) == 1:
    fails.append("every viewport wrapped identically — the probe measured nothing")

print()
if fails:
    print(f"FAIL ({len(fails)})")
    for f in fails:
        print("  -", f)
    sys.exit(1)
print(f"PASS — {len(report)} readings; no visual line ends with a separator, "
      "the mark is generated, and no separator element remains")
